def solve_afag(v, *, xp=np, c=None):
    v = dict(v)
    ref = v['tk1d']
    r = np.dtype(ref.dtype).type
    c = constants(ref.dtype) if c is None else c
    for key, value in c.items(): v.setdefault(key, value)
    _max = lambda *x: maximum(*x, xp=xp)
    _min = lambda *x: minimum(*x, xp=xp)
    _int = lambda x: xp.asarray(x, dtype=np.int32)
    _nint = lambda x: nint(x, xp=xp)
    _double = lambda x: xp.asarray(x, dtype=np.float64)
    _max0 = lambda x: xp.fmax(r(0), x)
    _real = lambda x: xp.asarray(x, dtype=ref.dtype)
    _erf = lambda x: erf(x, xp=xp)
    _get_local = lambda x, i: get_local(x, i, xp=xp)
    alive = True
    v.setdefault('g3m1d', r(0))
    v.setdefault('best0', r(0))
    v.setdefault('lamgmin', r(0))
    v.setdefault('lamgmax', r(0))
    v.setdefault('kdx', r(0))
    v.setdefault('kinv', r(0))
    v.setdefault('gg1', r(0))
    v.setdefault('c1x2', r(0))
    v.setdefault('vta1', r(0))
    v.setdefault('vtb1', r(0))
    v.setdefault('best', r(0))
    v.setdefault('gmlr', r(0))
    v.setdefault('bdg', r(0))
    v.setdefault('fdg', r(0))
    v.setdefault('ltk', r(0))
    v.setdefault('lqg', r(0))
    v.setdefault('mdg', r(0))
    if v['ice_rhog'] == 0:
        v['rhog'] = xp.where(xp.logical_and(True, alive), xp.asarray(v['rhog1'], dtype=ref.dtype), v['rhog'])  # WRF:1275
        v['vg1d'] = xp.where(xp.logical_and(True, alive), xp.asarray(r(0.0), dtype=ref.dtype), v['vg1d'])  # WRF:1276
    elif np.logical_or(v['ice_rhog'] == 1, v['ice_rhog'] == 2):
        v['rhog'] = xp.where(xp.logical_and(True, alive), xp.asarray(v['qg1d'] / (v['vg1d'] + v['ismall']), dtype=ref.dtype), v['rhog'])  # WRF:1278
        m1 = xp.logical_and(True, v['tk1d'] >= v['tk0c'])
        t1 = m1
        m2 = xp.logical_and(m1, v['rhog'] > v['rhoh'])
        t2 = m2
        v['rhog'] = xp.where(xp.logical_and(m2, alive), xp.asarray(v['rhoh'], dtype=ref.dtype), v['rhog'])  # WRF:1281
        m3 = xp.logical_and(True, xp.logical_not(t1))
        m4 = xp.logical_and(m3, v['rhog'] > v['rhog0'])
        t4 = m4
        v['rhog'] = xp.where(xp.logical_and(m4, alive), xp.asarray(v['rhog0'], dtype=ref.dtype), v['rhog'])  # WRF:1285
        m5 = xp.logical_and(True, v['rhog'] < v['rhoimin'])
        t5 = m5
        v['rhog'] = xp.where(xp.logical_and(m5, alive), xp.asarray(v['rhoimin'], dtype=ref.dtype), v['rhog'])  # WRF:1289
        v['vg1d'] = xp.where(xp.logical_and(True, alive), xp.asarray(v['qg1d'] / v['rhog'], dtype=ref.dtype), v['vg1d'])  # WRF:1291
    m6 = xp.logical_and(True, v['ng1d'] < v['nsmall'])
    t6 = m6
    v['ltk'] = xp.where(xp.logical_and(m6, alive), xp.asarray(xp.log(v['tk1d']), dtype=ref.dtype), v['ltk'])  # WRF:1294
    v['lqg'] = xp.where(xp.logical_and(m6, alive), xp.asarray(r(-1.0) * xp.log(v['qg1d']), dtype=ref.dtype), v['lqg'])  # WRF:1295
    v['mdg'] = xp.where(xp.logical_and(m6, alive), xp.asarray(xp.exp(r(-2205.8027) + r(1225.8046) * v['ltk'] - r(226.27995) * xp.power(v['ltk'], r(2.0)) + r(13.929644) * xp.power(v['ltk'], r(3.0)) - r(0.25) * v['lqg']) / r(1000.0), dtype=ref.dtype), v['mdg'])  # WRF:1296
    v['ng1d'] = xp.where(xp.logical_and(m6, alive), xp.asarray(r(1000000000.0) * v['qg1d'] * v['v2m3'] / v['rhog'] / xp.power(v['mdg'], r(3.0)), dtype=ref.dtype), v['ng1d'])  # WRF:1298
