        v['kdx'] = xp.where(xp.logical_and(m10, alive), xp.asarray(_max(v['kcgmin'], _min(v['kcgmax'], xp.power(v['bdg'] / v['fdg'], r(3.0)))), dtype=ref.dtype), v['kdx'])  # WRF:1339
        v['afag'] = xp.where(xp.logical_and(m10, alive), xp.asarray((r(6.0) * v['kdx'] - r(3.0) + xp.sqrt(r(8.0) * v['kdx'] + r(1.0))) / (r(2.0) - r(2.0) * v['kdx']), dtype=ref.dtype), v['afag'])  # WRF:1340
