    v['lamg'] = xp.where(xp.logical_and(m10, alive), xp.asarray(xp.power(xp.exp(gamln(v['afag'] + r(4.0), xp=xp) - gamln(v['afag'] + r(1.0), xp=xp)) * v['ng1d'] / v['g3m1d'], v['thrd']), dtype=ref.dtype), v['lamg'])  # WRF:1345
    v['lamgmin'] = xp.where(xp.logical_and(True, alive), xp.asarray(xp.power(xp.exp(gamln(v['afag'] + r(4.0), xp=xp) - gamln(v['afag'] + r(1.0), xp=xp)), v['thrd']) / v['dgmax'], dtype=ref.dtype), v['lamgmin'])  # WRF:1347
    v['lamgmax'] = xp.where(xp.logical_and(True, alive), xp.asarray(xp.power(xp.exp(gamln(v['afag'] + r(4.0), xp=xp) - gamln(v['afag'] + r(1.0), xp=xp)), v['thrd']) / v['dgmin'], dtype=ref.dtype), v['lamgmax'])  # WRF:1348
