def solve_afah(v, *, xp=np, c=None):
    v = dict(v)
    ref = v['tk1d']
    r = np.dtype(ref.dtype).type
    c = constants(ref.dtype) if c is None else c
    for key, value in c.items(): v.setdefault(key, value)
    _max = lambda *x: maximum(*x, xp=xp)
    _min = lambda *x: minimum(*x, xp=xp)
    _int = lambda x: xp.asarray(x, dtype=np.int32)
    _nint = lambda x: nint(x, xp=xp)
    _double = lambda x: xp.asarray(x, dtype=np.float64)
    _max0 = lambda x: xp.fmax(r(0), x)
    _real = lambda x: xp.asarray(x, dtype=ref.dtype)
    _erf = lambda x: erf(x, xp=xp)
    _get_local = lambda x, i: get_local(x, i, xp=xp)
    alive = True
    v.setdefault('h3m1d', r(0))
    v.setdefault('best0', r(0))
    v.setdefault('gh1', r(0))
    v.setdefault('kdx', r(0))
    v.setdefault('lamhmin', r(0))
    v.setdefault('lamhmax', r(0))
    v.setdefault('kinv', r(0))
    v.setdefault('c1x2', r(0))
    v.setdefault('vta1', r(0))
    v.setdefault('vtb1', r(0))
    v.setdefault('best', r(0))
    v.setdefault('bdh', r(0))
    v.setdefault('fdh', r(0))
    v.setdefault('ltk', r(0))
    v.setdefault('lqh', r(0))
    m1 = xp.logical_and(True, v['nh1d'] < v['nsmall'])
    t1 = m1
    v['ltk'] = xp.where(xp.logical_and(m1, alive), xp.asarray(xp.log(v['tk1d']), dtype=ref.dtype), v['ltk'])  # WRF:1385
    v['lqh'] = xp.where(xp.logical_and(m1, alive), xp.asarray(r(-1.0) * xp.log(v['qh1d']), dtype=ref.dtype), v['lqh'])  # WRF:1386
    v['nh1d'] = xp.where(xp.logical_and(m1, alive), xp.asarray(xp.exp(r(22.929406) - r(4.2328364) * v['ltk'] + r(0.30647567) * xp.power(v['ltk'], r(2.0)) - r(0.009233271) * xp.power(v['ltk'], r(3.0)) - r(0.25) * v['lqh']), dtype=ref.dtype), v['nh1d'])  # WRF:1387
    v['h3m1d'] = xp.where(xp.logical_and(True, alive), xp.asarray(v['qh1d'] * v['v2m3'] / v['rhoh'], dtype=ref.dtype), v['h3m1d'])  # WRF:1390
    m2 = xp.logical_and(True, xp.logical_and(v['h2m1d'] >= v['asmall'], v['h3m1d'] >= v['ismall']))
    t2 = m2
    v['kdx'] = xp.where(xp.logical_and(m2, alive), xp.asarray(_max0(xp.power(v['h2m1d'], r(3.0)) / (xp.power(v['h3m1d'], r(2.0)) * v['nh1d'])), dtype=ref.dtype), v['kdx'])  # WRF:1392
    m3 = xp.logical_and(m2, v['kdx'] > v['kchmax'])
    t3 = m3
    v['kdx'] = xp.where(xp.logical_and(m3, alive), xp.asarray(v['kchmin'], dtype=ref.dtype), v['kdx'])  # WRF:1394
    v['h2m1d'] = xp.where(xp.logical_and(m3, alive), xp.asarray(xp.power(v['kdx'] * v['nh1d'] * xp.power(v['h3m1d'], r(2.0)), v['thrd']), dtype=ref.dtype), v['h2m1d'])  # WRF:1395
    m4 = xp.logical_and(xp.logical_and(m2, xp.logical_not(t3)), v['kdx'] < v['kchmin'])
    t3 = xp.logical_or(t3, m4)
    v['kdx'] = xp.where(xp.logical_and(m4, alive), xp.asarray(v['kchmin'], dtype=ref.dtype), v['kdx'])  # WRF:1397
    v['h2m1d'] = xp.where(xp.logical_and(m4, alive), xp.asarray(xp.power(v['kdx'] * v['nh1d'] * xp.power(v['h3m1d'], r(2.0)), v['thrd']), dtype=ref.dtype), v['h2m1d'])  # WRF:1398
    v['afah'] = xp.where(xp.logical_and(m2, alive), xp.asarray((r(6.0) * v['kdx'] - r(3.0) + xp.sqrt(r(8.0) * v['kdx'] + r(1.0))) / (r(2.0) - r(2.0) * v['kdx']), dtype=ref.dtype), v['afah'])  # WRF:1400
    v['afah'] = xp.where(xp.logical_and(m2, alive), xp.asarray(_min(_max(v['afah'], v['afamin']), v['afamax']), dtype=ref.dtype), v['afah'])  # WRF:1401
