def large_dt(v, *, xp=np, c=None):
    v = dict(v)
    ref = v['dt']
    r = np.dtype(ref.dtype).type
    c = constants(ref.dtype) if c is None else c
    for key, value in c.items(): v.setdefault(key, value)
